# Generated by build.py from recipe.yml for recipe imap-check-the-flags-an-app-left. Do not edit.
set -e
cd "$(dirname "$0")"
surl --mail-domain example.com --mailbox ann@example.com:annpass --mailbox shop@example.com:shoppass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "{order1,order2,spam,news}.eml" smtp://127.0.0.1:8080/example.com
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 4 FLAGS" imap://127.0.0.1:8081/INBOX
curl -sS -o "read#1.eml" -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=[1-2]"
curl -sS -o /dev/null -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=3;SECTION=HEADER.FIELDS%20(SUBJECT)" --next -sS -o /dev/null -u ann@example.com:annpass -X "STORE 3 +FLAGS (\Deleted)" imap://127.0.0.1:8081/INBOX
curl -u ann@example.com:annpass -X "FETCH 1:* FLAGS" imap://127.0.0.1:8081/INBOX
kill $(jobs -p)
